parameters.jsCode:
const t = $items("When Executed by Another Workflow", 0, 0)[0].json;

let key = {};
let rawMsg = undefined;
try { key = JSON.parse(t.wa_message_key || "{}"); } catch (e) { key = {}; }
try { rawMsg = t.wa_message_raw ? JSON.parse(t.wa_message_raw) : undefined; } catch (e) { rawMsg = undefined; }

const base = String(t.wa_base_url || "").replace(/\/+$/, "");

return [{
  json: {
    has_inline: String(t.wa_inline_base64 || "").length > 0,
    inline_base64: t.wa_inline_base64 || "",
    url: base + "/chat/getBase64FromMediaMessage/" + encodeURIComponent(t.wa_instance || ""),
    apikey: t.wa_api_key || "",
    body: { message: { key: key, message: rawMsg }, convertToMp4: false }
  }
}];

const prep = $items("WA Prep", 0, 0)[0].json;
const t = $items("When Executed by Another Workflow", 0, 0)[0].json;

let b64 = "";
let mime = "";
let fileName = "";

if (prep.has_inline) {
  b64 = prep.inline_base64;
} else {
  const resp = $json || {};
  const d = resp.data && typeof resp.data === "object" ? resp.data : {};
  b64 = resp.base64 || resp.media || d.base64 || d.media || "";
  mime = resp.mimetype || resp.mimeType || d.mimetype || "";
  fileName = resp.fileName || resp.filename || d.fileName || "";
}

mime = mime || t.provider_mime || "";
fileName = fileName || t.provider_file_name || "";

if (!b64 || typeof b64 !== "string") {
  return [{ json: { ok: false, error_code: "PROVIDER_DOWNLOAD_FAILED", error_detail: "Evolution returned no media bytes" } }];
}

const buffer = Buffer.from(b64, "base64");
if (!buffer || buffer.length === 0) {
  return [{ json: { ok: false, error_code: "PROVIDER_DOWNLOAD_FAILED", error_detail: "empty media buffer" } }];
}

const binary = await this.helpers.prepareBinaryData(
  buffer,
  fileName || "file",
  mime || "application/octet-stream"
);

return [{
  json: { ok: true, provider_mime: mime, provider_file_name: fileName, provider_size_bytes: buffer.length },
  binary: { data: binary }
}];

const t = $items("When Executed by Another Workflow", 0, 0)[0].json;

// ---------------------------------------------------------------------------
// Normalise the attachment URL. It can arrive with surrounding whitespace /
// newlines, wrapping quotes, non-breaking spaces, or JSON-escaped slashes
// when it is threaded through expressions / executeWorkflow string inputs --
// any of which makes `new URL()` throw and drops a VALID Meta URL into the
// UNTRUSTED_MEDIA_HOST path (error_detail = "invalid attachment url").
// ---------------------------------------------------------------------------
let raw = String(t.fb_attachment_url == null ? "" : t.fb_attachment_url);
raw = raw
  .replace(/\\u002[fF]/g, "/")                 // JSON \u002f  -> /
  .replace(/\\\//g, "/")                        // JSON \/      -> /
  .replace(/[\u0000-\u0020\u007F\u00A0]+/g, "") // all controls / spaces / NBSP, anywhere
  .replace(/^["']+/, "")
  .replace(/["']+$/, "");

// ---------------------------------------------------------------------------
// Extract the host exactly the way an HTTP client would: the authority
// segment between "://" and the first "/", "?" or "#", minus any
// "user:pass@" and ":port". Try the standard parser first (it may be
// unavailable or stricter in this Code sandbox), then fall back to a strict
// http(s)-only regex so a *valid* URL is never rejected just because the
// parser threw.
// ---------------------------------------------------------------------------
let host = "";
try {
  host = new URL(raw).hostname.toLowerCase();
} catch (e) {
  const m = raw.match(/^https?:\/\/([^/?#\s]+)/i);
  if (m && m[1]) {
    host = m[1].split("@").pop().split(":")[0].toLowerCase().trim();
  }
}

// ---------------------------------------------------------------------------
// Trusted-host allow-list -- UNCHANGED. SSRF guard tightened, not loosened:
// the host must be a plain domain (letters / digits / dot / hyphen only --
// no bracketed IPv6, no "%", no embedded credentials, no leading/trailing
// dot) AND end with one of the Meta-owned suffixes.
// ---------------------------------------------------------------------------
const ALLOWED = [".fbcdn.net", ".fbsbx.com", ".facebook.com", ".cdninstagram.com", ".whatsapp.net"];
const okHost =
  !!host &&
  /^[a-z0-9.-]+$/.test(host) &&
  !host.startsWith(".") &&
  !host.endsWith(".") &&
  ALLOWED.some((s) => host === s.slice(1) || host.endsWith(s));

if (!okHost) {
  return [{ json: { ok: false, fb_host_ok: false, error_code: "UNTRUSTED_MEDIA_HOST", error_detail: host || ("unparseable: " + raw.slice(0, 160)) || "invalid attachment url" } }];
}

// ---------------------------------------------------------------------------
// access_token append -- behaviour preserved: normalised valid URL + the
// owning Page Access Token, with correct "?" / "&" handling, a guard
// against a trailing "?" / "&", and a no-op if an access_token is already
// present.
// ---------------------------------------------------------------------------
const token = String(t.fb_page_token == null ? "" : t.fb_page_token).trim();
let downloadUrl = raw;
if (token && !/[?&]access_token=/.test(raw)) {
  const base = raw.replace(/[?&]+$/, "");
  const sep = base.indexOf("?") === -1 ? "?" : "&";
  downloadUrl = base + sep + "access_token=" + encodeURIComponent(token);
}

return [{ json: { fb_host_ok: true, fb_url: raw, fb_download_url: downloadUrl } }];

const t = $items("When Executed by Another Workflow", 0, 0)[0].json;
const sign = $items("Sign Upload", 0, 0)[0].json || {};

if (sign.success !== true || !sign.signed_url) {
  return [{ json: { ok: false, error_code: sign.code || "SIGN_UPLOAD_FAILED", error_detail: sign.message || "no signed upload url" } }];
}

const messageType = String(t.message_type || "");
const PER_TYPE = { image: 5 * 1024 * 1024, audio: 10 * 1024 * 1024, document: 20 * 1024 * 1024 };
const HARD_MAX = 25 * 1024 * 1024;

const incoming = $json || {};
if (incoming.ok === false) {
  return [{ json: { ok: false, error_code: incoming.error_code || "PROVIDER_DOWNLOAD_FAILED", error_detail: incoming.error_detail || null } }];
}

const bin = ($binary && $binary.data) ? $binary.data : null;
if (!bin) {
  return [{ json: { ok: false, error_code: "PROVIDER_DOWNLOAD_FAILED", error_detail: "no media bytes after download" } }];
}

let buffer;
try {
  buffer = await this.helpers.getBinaryDataBuffer(0, "data");
} catch (e) {
  return [{ json: { ok: false, error_code: "PROVIDER_DOWNLOAD_FAILED", error_detail: "could not read downloaded bytes" } }];
}
const size = buffer ? buffer.length : 0;
if (!size) {
  return [{ json: { ok: false, error_code: "PROVIDER_DOWNLOAD_FAILED", error_detail: "empty media" } }];
}

// MIME resolution -- prefer a SPECIFIC provider-declared type over the
// download's Content-Type. api.telegram.org/file often serves media as
// application/octet-stream, which previously failed the family check for
// image/voice/audio. A generic octet-stream is treated as "unknown", not
// as a mismatch.
const GENERIC = new Set(["", "application/octet-stream", "binary/octet-stream", "application/binary", "application/download", "*/*"]);
const specific = (m) => {
  const s = String(m || "").split(";")[0].trim().toLowerCase();
  return GENERIC.has(s) ? "" : s;
};
let mime =
  specific(incoming.provider_mime) ||   // WhatsApp (enriched in WA To Binary)
  specific(t.provider_mime) ||          // Telegram (from the message object) / WA
  specific(bin.mimeType) ||             // download Content-Type (if specific)
  String(bin.mimeType || "").split(";")[0].trim().toLowerCase() ||
  "";
if (messageType === "image" && !mime) mime = "image/jpeg";
if (messageType === "audio" && !mime) mime = "audio/ogg";
if (!mime) mime = "application/octet-stream";

function sanitizeFileName(name) {
  const b = String(name || "").split(/[/\\]/).pop() || "file";
  const c = b.replace(/[^a-zA-Z0-9._-]+/g, "_").replace(/_{2,}/g, "_").slice(0, 120);
  return c || "file";
}
// Best-available filename. The parent's provider_file_name is the most
// authoritative (real Telegram document/audio/video name, or a meaningful
// telegram_<type>_<id> fallback). n8n's own auto-name for a downloaded
// binary looks like "file_6.mp4" (it comes from the Telegram file server's
// internal path segment) -- never use that as the "original" name.
const isAutoName = (s) => /^file_\d+(\.[a-z0-9]{1,8})?$/i.test(String(s || "").trim());
function pickName() {
  for (const cand of arguments) {
    const s = String(cand || "").trim();
    if (s && !isAutoName(s)) return s;
  }
  return "";
}
// MIME -> extension. A real filename (Telegram's, or the download's
// Content-Disposition header) always carries an extension, so a picked
// name WITHOUT one is not trustworthy (a Meta CDN hash, or the empty
// segment before "/?params") -> deterministic "<type>_file.<ext>".
// NEVER derive the extension by slicing the MIME subtype
// ("application/vnd.openxmlformats-...-presentation" is .pptx, not
// ".vndopenx").
const MIME_EXT = {
  "application/pdf": "pdf",
  "application/msword": "doc",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
  "application/vnd.ms-excel": "xls",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
  "application/vnd.ms-powerpoint": "ppt",
  "application/vnd.openxmlformats-officedocument.presentationml.presentation": "pptx",
  "text/plain": "txt", "text/csv": "csv", "application/csv": "csv",
  "text/tab-separated-values": "tsv", "application/rtf": "rtf", "text/rtf": "rtf",
  "application/json": "json", "text/markdown": "md",
  "application/zip": "zip", "application/x-zip-compressed": "zip",
  "application/gzip": "gz", "application/x-7z-compressed": "7z",
  "application/x-rar-compressed": "rar", "application/vnd.rar": "rar",
  "image/jpeg": "jpg", "image/pjpeg": "jpg", "image/png": "png", "image/gif": "gif",
  "image/webp": "webp", "image/bmp": "bmp", "image/tiff": "tiff",
  "image/heic": "heic", "image/heif": "heif", "image/svg+xml": "svg",
  "audio/mpeg": "mp3", "audio/mp3": "mp3", "audio/mp4": "m4a", "audio/x-m4a": "m4a",
  "audio/aac": "aac", "audio/ogg": "ogg", "audio/opus": "ogg", "audio/wav": "wav",
  "audio/x-wav": "wav", "audio/webm": "webm", "audio/flac": "flac", "audio/amr": "amr",
  "video/mp4": "mp4", "video/quicktime": "mov", "video/webm": "webm",
  "video/3gpp": "3gp", "video/x-matroska": "mkv"
};
function extFromMime(m) {
  const s = String(m || "").split(";")[0].trim().toLowerCase();
  if (MIME_EXT[s]) return MIME_EXT[s];
  const sub = (s.split("/")[1] || "").replace(/^x-/, "").replace(/\+.*$/, "").replace(/[^a-z0-9]/gi, "");
  if (sub && sub.length <= 5 && !/octet|stream|binary|download/.test(sub)) return sub;
  return "";
}
const pickedName = sanitizeFileName(
  pickName(t.provider_file_name, incoming.provider_file_name, bin.fileName)
);
let fileName;
if (pickedName && /\.[a-z0-9]{1,8}$/i.test(pickedName)) {
  fileName = pickedName;
} else {
  const fallbackExt =
    extFromMime(mime) ||
    (messageType === "image" ? "jpg" : messageType === "audio" ? "ogg" : "bin");
  fileName = messageType + "_file." + fallbackExt;
}

const perType = PER_TYPE[messageType];
if (size > HARD_MAX || (perType && size > perType)) {
  return [{ json: { ok: false, error_code: "FILE_TOO_LARGE", error_detail: "size " + size + " exceeds limit for " + messageType } }];
}

// Family check: only fail on a DIFFERENT concrete family (e.g. a text/html
// error page returned instead of an image). A generic octet-stream is not a
// mismatch -- accept it under the declared message_type.
const fam = mime.split("/")[0];
const genericFam = mime === "application/octet-stream" || mime === "binary/octet-stream";
if (messageType === "image" && !genericFam && fam !== "image") {
  return [{ json: { ok: false, error_code: "MIME_MISMATCH", error_detail: mime } }];
}
if (messageType === "audio" && !genericFam && fam !== "audio") {
  return [{ json: { ok: false, error_code: "MIME_MISMATCH", error_detail: mime } }];
}

bin.mimeType = mime;
bin.fileName = fileName;

return [{
  json: {
    ok: true,
    message_type: messageType,
    media_mime_type: mime,
    media_file_name: fileName,
    media_size_bytes: size,
    media_path: sign.path,
    signed_url: sign.signed_url
  },
  binary: { data: bin }
}];

const v = $items("Post-Download Validate", 0, 0)[0].json;
const putResp = $json || {};

const putOk = !!(putResp && (putResp.Key || putResp.key || putResp.Id || putResp.id || putResp.path || putResp.fullPath));
if (!putOk) {
  return [{ json: { ok: false, error_code: "STORAGE_UPLOAD_FAILED", error_detail: JSON.stringify(putResp).slice(0, 300) } }];
}

return [{
  json: {
    ok: true,
    message_type: v.message_type,
    media_path: v.media_path,
    media_mime_type: v.media_mime_type,
    media_file_name: v.media_file_name,
    media_size_bytes: v.media_size_bytes
  }
}];

const j = $json || {};
return [{
  json: {
    ok: false,
    error_code: j.error_code || "MEDIA_INGEST_FAILED",
    error_detail: j.error_detail || j.message || null
  }
}];
